INSERT INTO scholarships (scholarship_id, slug, name, provider_id, scope, category_id, currency_code, amount_original, amount_inr, amount_note, amount_period, num_awards, deadline, deadline_note, all_fields, all_india, host_any, host_note, open_to_all_nationalities, max_income_inr, min_percentage, gender_eligibility, special_eligibility, required_profile_flag, description, application_process, official_url, status, last_verified, data_source, external_id, fetched_at) VALUES
  (1, 'central-sector-scheme-of-scholarships-for-college-and-university-students', 'Central Sector Scheme of Scholarships for College and University Students', 1, 'National', 1, 'INR', 12000, 12000, '₹12,000/year (UG, first 3 years); ₹20,000/year (PG)', 'Annual', 82000, '2026-10-31', 'NSP 2026-27 cycle (verify on NSP)', 1, 1, 0, NULL, 0, 450000, NULL, 'All', 'Above 80th percentile of successful candidates in Class 12 (own board & stream)', NULL, 'Merit-cum-means scholarship for students in the top 20 percentile of their Class 12 board who are in regular UG/PG courses. 50% of slots are for girls; SC/ST/OBC reservation applies.', 'Apply (fresh or renewal) on the National Scholarship Portal; institute and board verify. Renewal needs 50% marks and 75% attendance.', 'https://scholarships.gov.in', 'Open', '2026-10-18', 'manual', 'central-sector-scheme-of-scholarships-for-college-and-university-students', NULL),
  (2, 'post-matric-scholarship-for-scheduled-caste-students', 'Post-Matric Scholarship for Scheduled Caste Students', 2, 'National', 5, 'INR', NULL, NULL, 'Tuition & non-refundable fees reimbursed + monthly academic allowance (rate depends on course group)', 'Annual', NULL, NULL, 'Set by each state; usually Oct–Dec', 1, 1, 0, NULL, 0, 250000, NULL, 'All', NULL, NULL, 'Centrally sponsored scheme that funds SC students for any recognised post-matric course, from Class 11 to PhD. Implemented through state SC welfare departments.', 'Apply on NSP or your state''s scholarship portal (e.g. MahaDBT); funds are paid by DBT.', 'https://scholarships.gov.in', 'Open', '2026-10-18', 'manual', 'post-matric-scholarship-for-scheduled-caste-students', NULL),
  (3, 'aicte-pragati-scholarship-for-girl-students', 'AICTE Pragati Scholarship for Girl Students', 3, 'National', 4, 'INR', 50000, 50000, '₹50,000/year (degree: up to 4 years; diploma: up to 3 years)', 'Annual', NULL, '2026-10-31', 'Tentative, NSP 2026-27', 0, 1, 0, NULL, 0, 800000, NULL, 'Female', 'Girl students; up to two girls per family; first year (or lateral-entry second year) of an AICTE-approved technical course', NULL, 'AICTE scheme for students in AICTE-approved technical degree or diploma courses. Girl students; up to two girls per family.', 'Apply on the National Scholarship Portal; the institute verifies the application.', 'https://scholarships.gov.in', 'Open', '2026-10-18', 'manual', 'aicte-pragati-scholarship-for-girl-students', NULL),
  (4, 'aicte-saksham-scholarship-for-specially-abled-students', 'AICTE Saksham Scholarship for Specially-Abled Students', 3, 'National', 6, 'INR', 50000, 50000, '₹50,000/year (degree: up to 4 years; diploma: up to 3 years)', 'Annual', NULL, '2026-10-31', 'Tentative, NSP 2026-27', 0, 1, 0, NULL, 0, 800000, NULL, 'All', 'Benchmark disability of 40% or more; first year (or lateral-entry second year) of an AICTE-approved technical course', 'Disability', 'AICTE scheme for students in AICTE-approved technical degree or diploma courses. Benchmark disability of 40% or more.', 'Apply on the National Scholarship Portal; the institute verifies the application.', 'https://scholarships.gov.in', 'Open', '2026-10-18', 'manual', 'aicte-saksham-scholarship-for-specially-abled-students', NULL),
  (5, 'aicte-swanath-scholarship', 'AICTE Swanath Scholarship', 3, 'National', 2, 'INR', 50000, 50000, '₹50,000/year (degree: up to 4 years; diploma: up to 3 years)', 'Annual', NULL, '2026-10-31', 'Tentative, NSP 2026-27', 0, 1, 0, NULL, 0, 800000, NULL, 'All', 'Orphans, wards of parents who died of COVID-19, or wards of martyred armed forces / CAPF personnel; first year (or lateral-entry second year) of an AICTE-approved technical course', 'Orphan / Ward of Armed Forces', 'AICTE scheme for students in AICTE-approved technical degree or diploma courses. Orphans, wards of parents who died of COVID-19, or wards of martyred armed forces / CAPF personnel.', 'Apply on the National Scholarship Portal; the institute verifies the application.', 'https://scholarships.gov.in', 'Open', '2026-10-18', 'manual', 'aicte-swanath-scholarship', NULL),
  (6, 'aicte-pg-scholarship-gate-gpat-ceed', 'AICTE PG Scholarship (GATE / GPAT / CEED)', 3, 'National', 1, 'INR', 148800, 148800, '₹12,400/month for up to 24 months', 'Monthly', NULL, NULL, 'Portal usually opens around September', 0, 1, 0, NULL, 0, NULL, NULL, 'All', 'Valid GATE, GPAT or CEED score; admitted to an AICTE-approved M.E./M.Tech/M.Arch/M.Pharm/M.Des', NULL, 'Monthly stipend for GATE/GPAT/CEED-qualified students in AICTE-approved full-time postgraduate programmes.', 'The institute registers eligible students on AICTE''s PG scholarship portal; stipend paid monthly by DBT.', 'https://aicte.gov.in', 'Open', '2026-10-18', 'manual', 'aicte-pg-scholarship-gate-gpat-ceed', NULL),
  (7, 'national-overseas-scholarship-for-sc-students', 'National Overseas Scholarship for SC Students', 2, 'International', 9, 'USD', 15400, 1314000, 'Full tuition + US$15,400/yr maintenance (UK: £9,900) + contingency, airfare, visa and insurance', 'Annual', 125, NULL, 'Round 1 Feb–Mar, Round 2 Sep–Oct (40 days each)', 1, 1, 1, 'Any country', 0, 800000, 60, 'All', 'Unconditional offer from a QS top-500 university; age 35 or under; 30% of awards for women', NULL, 'Government of India scholarship for SC (also denotified/nomadic tribes and landless labourer families) students pursuing a master''s or PhD abroad.', 'Apply online at nosmsje.gov.in in one of two rounds; selection on merit within category quotas.', 'https://nosmsje.gov.in', 'Open', '2026-10-18', 'manual', 'national-overseas-scholarship-for-sc-students', NULL),
  (8, 'inspire-scholarship-for-higher-education-she', 'INSPIRE Scholarship for Higher Education (SHE)', 4, 'National', 3, 'INR', 80000, 80000, '₹80,000/year', 'Annual', 10000, NULL, 'Annual call, usually Oct–Dec', 0, 1, 0, NULL, 0, NULL, NULL, 'All', 'Top 1% in Class 12 board, or JEE-Advanced/NEET top 10,000, or admission to IISER/NISER/CEBS; age 17–22', NULL, 'DST scholarship with mentorship for talented students pursuing BSc/MSc (or integrated MS) in the natural and basic sciences.', 'Apply on the online-inspire.gov.in portal once the annual call is announced.', 'https://online-inspire.gov.in', 'Open', '2026-10-18', 'manual', 'inspire-scholarship-for-higher-education-she', NULL),
  (9, 'top-class-education-scheme-for-sc-students', 'Top Class Education Scheme for SC Students', 2, 'National', 5, 'INR', 286000, 286000, 'Full tuition (capped at ₹2 lakh/yr in private institutes) + ₹86,000 first-year allowance (₹41,000 later years)', 'Annual', NULL, '2026-10-31', 'NSP 2026-27 cycle', 1, 1, 0, NULL, 0, 800000, NULL, 'All', 'Admission to a notified premier institution (IITs, IIMs, NITs, AIIMS, NLUs etc.); 30% slots for girls', NULL, 'Covers full fees and living, book and computer costs for SC students who secure admission to notified top-class institutions.', 'Apply on the National Scholarship Portal; the institution verifies.', 'https://scholarships.gov.in', 'Open', '2026-10-18', 'manual', 'top-class-education-scheme-for-sc-students', NULL),
  (10, 'prime-ministers-scholarship-scheme-pmss-for-wards-of-ex-servicemen', 'Prime Minister''s Scholarship Scheme (PMSS) for Wards of Ex-Servicemen', 5, 'National', 8, 'INR', 36000, 36000, '₹3,000/month for girls, ₹2,500/month for boys (paid annually)', 'Annual', NULL, '2026-12-31', 'Fresh applications 2026-27', 0, 1, 0, NULL, 0, NULL, 60, 'All', 'Dependent wards/widows of ex-servicemen and ex-Coast Guard personnel; first year of a professional/technical course (MBA/MCA also allowed)', 'Orphan / Ward of Armed Forces', 'Scholarship for wards and widows of ex-servicemen and ex-Coast Guard personnel pursuing professional degree courses.', 'Apply online on the Kendriya Sainik Board portal; verified by the Zila Sainik Board.', 'https://desw.gov.in/prime-ministers-scholarship-scheme-pmss', 'Open', '2026-10-18', 'manual', 'prime-ministers-scholarship-scheme-pmss-for-wards-of-ex-servicemen', NULL),
  (11, 'prime-ministers-research-fellowship-pmrf', 'Prime Minister''s Research Fellowship (PMRF)', 6, 'National', 7, 'INR', 840000, 840000, '₹70,000/month (yrs 1–2), ₹75,000 (yr 3), ₹80,000 (yrs 4–5) + ₹2 lakh/yr research grant', 'Monthly', NULL, '2026-10-31', 'Current cycle; cycles run twice a year', 0, 1, 0, NULL, 0, NULL, NULL, 'All', 'PhD admission at a PMRF granting institution (IITs, IISc, IISERs, NITs, select central universities); CGPA 8.0+ (direct entry)', NULL, 'India''s flagship doctoral fellowship for top students joining PhD programmes at premier institutes in science and technology.', 'Get admitted to a PhD at a granting institute, which nominates you; complete the application on the PMRF portal.', 'https://www.pmrf.in', 'Open', '2026-10-18', 'manual', 'prime-ministers-research-fellowship-pmrf', NULL),
  (12, 'post-matric-scholarship-for-scheduled-tribe-students', 'Post-Matric Scholarship for Scheduled Tribe Students', 7, 'National', 5, 'INR', 12000, 12000, 'Course fees (GoI cap ₹2.5 lakh engg / ₹6 lakh MBBS at private institutes) + stipend up to ₹1,200/month (hostellers, professional courses)', 'Annual', NULL, NULL, 'State portals; suggested registration window 1 Apr–30 Sep', 1, 1, 0, NULL, 0, 250000, NULL, 'All', NULL, NULL, 'Funds ST students in any recognised post-matric course from Class 11 to postgraduate level; extra allowance for students with disabilities.', 'Apply on your state/UT scholarship portal (or NSP where the state has none); tracked on dbttribal.gov.in.', 'https://tribal.nic.in/ScholarshiP.aspx', 'Open', '2026-10-18', 'manual', 'post-matric-scholarship-for-scheduled-tribe-students', NULL),
  (13, 'pm-yasasvi-post-matric-scholarship-for-obc-ebc-and-dnt-students', 'PM YASASVI Post-Matric Scholarship for OBC, EBC and DNT Students', 2, 'National', 5, 'INR', NULL, NULL, 'Tuition/non-refundable fees + academic allowance (varies by course and state)', 'Annual', NULL, '2026-10-31', 'NSP 2026-27 cycle', 1, 1, 0, NULL, 0, 250000, NULL, 'All', 'Also open to Economically Backward Classes (EBC) and De-notified Tribes (DNT)', NULL, 'Umbrella scheme (PM YASASVI) supporting OBC, EBC and DNT students in post-matric education.', 'Apply on NSP or the state scholarship portal.', 'https://scholarships.gov.in', 'Open', '2026-10-18', 'manual', 'pm-yasasvi-post-matric-scholarship-for-obc-ebc-and-dnt-students', NULL),
  (14, 'national-means-cum-merit-scholarship-nmmss', 'National Means-cum-Merit Scholarship (NMMSS)', 8, 'National', 1, 'INR', 12000, 12000, '₹12,000/year (₹1,000/month) from Class 9 to 12', 'Annual', 100000, '2026-11-30', 'Application deadline; state exam usually Nov–Dec', 1, 1, 0, NULL, 0, 350000, 55, 'All', 'Class 8 student of a government / aided / local-body school; must clear the state NMMS exam (MAT + SAT)', NULL, 'Prevents drop-out after Class 8 by supporting meritorious students from low-income families until Class 12.', 'Qualify the state-level NMMS exam, then apply on NSP; renew each year (55% in Class 9/11, 60% in Class 10).', 'https://scholarships.gov.in', 'Open', '2026-10-18', 'manual', 'national-means-cum-merit-scholarship-nmmss', NULL),
  (15, 'post-matric-scholarship-for-minorities', 'Post-Matric Scholarship for Minorities', 9, 'National', 5, 'INR', 12000, 12000, 'Admission & tuition fees + maintenance allowance up to ₹1,200/month for hostellers', 'Annual', NULL, '2026-10-31', 'NSP 2026-27 cycle', 1, 1, 0, NULL, 0, 200000, 50, 'All', 'Minority Community (Muslim, Christian, Sikh, Buddhist, Jain, Parsi); 30% for girls', 'Minority Community', 'Supports students from notified minority communities from Class 11 to PhD, including ITI and vocational courses.', 'Apply on the National Scholarship Portal.', 'https://scholarships.gov.in', 'Open', '2026-10-18', 'manual', 'post-matric-scholarship-for-minorities', NULL),
  (16, 'ishan-uday-special-scholarship-for-north-eastern-region', 'Ishan Uday Special Scholarship for North Eastern Region', 10, 'National', 2, 'INR', 78000, 78000, '₹5,400/month (general degree) or ₹7,800/month (technical/medical/professional), 10 months a year', 'Annual', 10000, '2026-10-31', 'NSP 2026-27 cycle', 1, 0, 0, NULL, 0, 450000, NULL, 'All', 'Domicile of a North-Eastern state; regular (not distance/part-time) UG course', NULL, 'UGC scholarship that helps students from the North-Eastern Region pursue general, technical and professional undergraduate degrees.', 'Apply on the National Scholarship Portal; the institute verifies.', 'https://scholarships.gov.in', 'Open', '2026-10-18', 'manual', 'ishan-uday-special-scholarship-for-north-eastern-region', NULL),
  (17, 'ugc-junior-research-fellowship-net-jrf', 'UGC Junior Research Fellowship (NET-JRF)', 10, 'National', 7, 'INR', 444000, 444000, '₹37,000/month (JRF, 2 yrs), ₹42,000/month (SRF, 3 yrs) + HRA + annual contingency', 'Monthly', NULL, NULL, 'Via UGC-NET, held June and December', 1, 1, 0, NULL, 0, NULL, 55, 'All', 'Qualify UGC-NET with JRF; age 30 or under at exam (relaxation for OBC-NCL/SC/ST/PwD/women)', NULL, 'Fellowship for NET-JRF qualified candidates pursuing a PhD in humanities, social sciences and other UGC-NET subjects.', 'Qualify UGC-NET (held twice a year by NTA), then join a PhD; the university processes the fellowship.', 'https://ugcnet.nta.nic.in', 'Open', '2026-10-18', 'manual', 'ugc-junior-research-fellowship-net-jrf', NULL),
  (18, 'national-fellowship-for-higher-education-of-st-students', 'National Fellowship for Higher Education of ST Students', 7, 'National', 7, 'INR', 372000, 372000, '₹31,000/month (JRF), ₹35,000/month (SRF) + HRA + contingency', 'Monthly', 750, '2026-10-31', 'Expected; verify on portal', 1, 1, 0, NULL, 0, NULL, 55, 'All', NULL, NULL, 'Fellowship for Scheduled Tribe students pursuing MPhil/PhD at recognised universities.', 'Apply on the national tribal fellowship portal; selection on PG marks if applicants exceed 750.', 'https://fellowship.tribal.gov.in', 'Open', '2026-10-18', 'manual', 'national-fellowship-for-higher-education-of-st-students', NULL),
  (19, 'national-scholarship-for-higher-education-of-st-students-top-class', 'National Scholarship for Higher Education of ST Students (Top Class)', 7, 'National', 5, 'INR', 286000, 286000, 'Full tuition (up to ₹2.5 lakh/yr at private institutes) + ₹3,000/month stipend + ₹5,000 books + ₹45,000 one-time computer', 'Annual', NULL, '2026-10-31', 'Expected; verify on NSP', 1, 1, 0, NULL, 0, 600000, NULL, 'All', 'Merit admission to a notified premier institution (not management quota)', NULL, 'Covers full costs for ST students admitted on merit to notified top institutions (IITs, IIMs, AIIMS, NITs etc.).', 'Apply on the National Scholarship Portal.', 'https://scholarships.gov.in', 'Open', '2026-10-18', 'manual', 'national-scholarship-for-higher-education-of-st-students-top-class', NULL),
  (20, 'reliance-foundation-undergraduate-scholarships', 'Reliance Foundation Undergraduate Scholarships', 11, 'National', 1, 'INR', 200000, 200000, 'Up to ₹2 lakh over the degree', 'Over full course', 5000, NULL, '2026-27 applications open; check site for closing date', 1, 1, 0, NULL, 0, NULL, NULL, 'All', 'First-year full-time UG students; merit-cum-means with an aptitude test', NULL, 'Merit-cum-means scholarship for first-year undergraduates in any stream, selected through an online aptitude test.', 'Apply online and take the aptitude test; no fee at any stage.', 'https://scholarships.reliancefoundation.org', 'Open', '2026-10-18', 'manual', 'reliance-foundation-undergraduate-scholarships', NULL);
INSERT INTO scholarships (scholarship_id, slug, name, provider_id, scope, category_id, currency_code, amount_original, amount_inr, amount_note, amount_period, num_awards, deadline, deadline_note, all_fields, all_india, host_any, host_note, open_to_all_nationalities, max_income_inr, min_percentage, gender_eligibility, special_eligibility, required_profile_flag, description, application_process, official_url, status, last_verified, data_source, external_id, fetched_at) VALUES
  (21, 'reliance-foundation-postgraduate-scholarships', 'Reliance Foundation Postgraduate Scholarships', 11, 'National', 3, 'INR', 600000, 600000, 'Up to ₹6 lakh over the degree', 'Over full course', 100, NULL, '2026-27 applications open; check site for closing date', 0, 1, 0, NULL, 0, NULL, NULL, 'All', 'First-year full-time PG students in engineering, technology, energy and life sciences', NULL, 'Merit-based scholarship for first-year postgraduates in future-ready science and technology disciplines.', 'Apply online; selection on academic merit, aptitude and interview.', 'https://scholarships.reliancefoundation.org', 'Open', '2026-10-18', 'manual', 'reliance-foundation-postgraduate-scholarships', NULL),
  (22, 'kotak-kanya-scholarship', 'Kotak Kanya Scholarship', 12, 'National', 4, 'INR', 150000, 150000, '₹1.5 lakh/year until graduation', 'Annual', NULL, NULL, 'Usually closes around September; 2026-27 cycle expected', 0, 1, 0, NULL, 0, 600000, 75, 'Female', 'Admission to an NIRF/NAAC-accredited institution in a professional course', NULL, 'Supports meritorious girls from low-income families in professional undergraduate degrees at reputed institutions.', 'Apply online via Buddy4Study; shortlisted students have a telephonic/virtual interview.', 'https://www.kotakeducationfoundation.org/kotak-kanya-scholarship', 'Open', '2026-10-18', 'manual', 'kotak-kanya-scholarship', NULL),
  (23, 'hdfc-bank-parivartan-ecss-programme', 'HDFC Bank Parivartan ECSS Programme', 13, 'National', 2, 'INR', 50000, 50000, '₹15,000–₹18,000 (school/diploma), ₹30,000 (general UG), ₹50,000 (professional UG), ₹35,000–₹75,000 (PG)', 'Annual', NULL, NULL, 'Usually July–August', 1, 1, 0, NULL, 0, 250000, 55, 'All', 'Preference to students facing a personal/family crisis in the last 3 years', NULL, 'Educational Crisis Scholarship Support that keeps students from low-income or crisis-hit families in school and college.', 'Apply online via Buddy4Study; documents verified followed by a telephonic interview.', 'https://www.parivartanecss.com', 'Open', '2026-10-18', 'manual', 'hdfc-bank-parivartan-ecss-programme', NULL),
  (24, 'ongc-foundation-scholarship', 'ONGC Foundation Scholarship', 14, 'National', 5, 'INR', 48000, 48000, '₹48,000/year', 'Annual', NULL, '2026-10-31', 'Per current cycle; verify on portal', 0, 1, 0, NULL, 0, 450000, 60, 'All', 'Income limit ₹4.5 lakh for SC/ST, ₹2 lakh for OBC/EWS; age 30 or under', NULL, 'ONGC''s scholarship for SC, ST, OBC and EWS students in engineering, MBBS, MBA and master''s in geology/geophysics.', 'Apply on the ONGC scholarship portal (NSP registration also required).', 'https://www.ongcscholar.org', 'Open', '2026-10-18', 'manual', 'ongc-foundation-scholarship', NULL),
  (25, 'tata-capital-pankh-scholarship', 'Tata Capital Pankh Scholarship', 15, 'National', 2, 'INR', 18000, 18000, 'Up to 80–100% of fees, capped at ₹10,000–₹15,000 (Class 11-12) or ₹12,000–₹18,000 (UG/diploma); higher for professional UG', 'Annual', NULL, NULL, 'Around Oct–Nov 2026 (sources differ)', 1, 1, 0, NULL, 0, 250000, 60, 'All', NULL, NULL, 'Tata Capital''s CSR scholarship covering most of the course fee for students from low-income families.', 'Apply online via Buddy4Study.', 'https://www.tatacapital.com/corporate-sustainability/education-uninterrupted.html', 'Open', '2026-10-18', 'manual', 'tata-capital-pankh-scholarship', NULL),
  (26, 'santoor-womens-scholarship', 'Santoor Women''s Scholarship', 16, 'National', 4, 'INR', 30000, 30000, '₹30,000/year for the 3-year degree', 'Annual', 1000, NULL, 'Late November 2026', 1, 0, 0, NULL, 0, NULL, NULL, 'Female', 'Studied Class 10 and 12 in government schools; joined UG straight after Class 12', NULL, 'Supports young women from government schools in four states to pursue full-time undergraduate degrees.', 'Apply online on the Santoor scholarship portal.', 'https://www.santoorscholarships.com', 'Open', '2026-10-18', 'manual', 'santoor-womens-scholarship', NULL),
  (27, 'lic-golden-jubilee-scholarship', 'LIC Golden Jubilee Scholarship', 17, 'National', 2, 'INR', 40000, 40000, '₹40,000/yr medicine, ₹30,000/yr engineering, ₹20,000/yr other UG/diploma/ITI, ₹15,000 special (after Class 10)', 'Annual', NULL, '2026-12-15', 'Applications usually open late October', 1, 1, 0, NULL, 0, 450000, 60, 'All', 'First-year students; passed Class 10/12/diploma in last 3 years', NULL, 'LIC''s scholarship for students from low-income families entering medicine, engineering, other degrees, diplomas or ITI.', 'Apply on LIC''s Golden Jubilee scholarship portal; selection by divisional office.', 'https://licindia.in', 'Open', '2026-10-18', 'manual', 'lic-golden-jubilee-scholarship', NULL),
  (28, 'sitaram-jindal-foundation-scholarship', 'Sitaram Jindal Foundation Scholarship', 18, 'National', 2, 'INR', 38400, 38400, '₹500–₹3,200/month depending on course (+₹1,000–1,200 for hostellers)', 'Monthly', NULL, NULL, 'Rolling / verify on site', 1, 1, 0, NULL, 0, 400000, NULL, 'All', 'Minimum marks vary by course and gender (e.g. Class 11-12: boys 60–65%, girls 55–60%)', NULL, 'Long-running monthly scholarship for students from Class 11 to PG from modest-income families.', 'Apply online on the foundation''s portal.', 'https://www.sitaramjindalfoundation.org', 'Open', '2026-10-18', 'manual', 'sitaram-jindal-foundation-scholarship', NULL),
  (29, 'rajarshi-chhatrapati-shahu-maharaj-shikshan-shulkh-shishyavrutti-yojana', 'Rajarshi Chhatrapati Shahu Maharaj Shikshan Shulkh Shishyavrutti Yojana', 19, 'National', 2, 'INR', NULL, NULL, 'Tuition fee reimbursement: 100% (non-professional, income ≤ ₹8 lakh); professional courses 100% (≤ ₹2.5 lakh) or 50% (₹2.5–8 lakh)', 'Annual', NULL, NULL, '2026-27 cycle expected; previous cycle closed 30 Sep', 1, 0, 0, NULL, 0, 800000, NULL, 'All', 'Admission through CAP to a government/aided/approved institution; regular courses only', NULL, 'Maharashtra fee reimbursement scheme (EBC) for open-category and EWS students in higher education.', 'Apply on the MahaDBT portal; the college and directorate verify.', 'https://mahadbt.maharashtra.gov.in', 'Open', '2026-10-18', 'manual', 'rajarshi-chhatrapati-shahu-maharaj-shikshan-shulkh-shishyavrutti-yojana', NULL),
  (30, 'swami-vivekananda-merit-cum-means-scholarship-svmcm', 'Swami Vivekananda Merit-cum-Means Scholarship (SVMCM)', 20, 'National', 1, 'INR', 96000, 96000, '₹1,000–₹8,000/month depending on course and level', 'Annual', NULL, '2026-10-31', 'Verify on portal', 1, 0, 0, NULL, 0, 250000, 60, 'All', 'Study in a recognised West Bengal institution; 60% for HS/UG (53–55% for PG)', NULL, 'West Bengal''s merit-cum-means scholarship for meritorious students from low-income families, Class 11 to PG.', 'Apply on the SVMCM portal; institute and department verify.', 'https://svmcm.wbhed.gov.in', 'Open', '2026-10-18', 'manual', 'swami-vivekananda-merit-cum-means-scholarship-svmcm', NULL),
  (31, 'mukhyamantri-yuva-swavalamban-yojana-mysy', 'Mukhyamantri Yuva Swavalamban Yojana (MYSY)', 21, 'National', 1, 'INR', 200000, 200000, '50% fee support up to ₹2 lakh/yr (medical), ₹50,000 (engineering), ₹25,000 (diploma), ₹10,000 (other UG) + hostel ₹12,000/yr + books', 'Annual', NULL, '2026-10-31', 'Applications open from July', 1, 0, 0, NULL, 0, 600000, 80, 'All', '80 percentile/marks in Class 10 (for diploma) or Class 12 (for degree)', NULL, 'Gujarat scheme covering half the fees, hostel and book costs for meritorious students from families earning up to ₹6 lakh.', 'Apply on the MYSY portal, then verify documents at a help centre.', 'https://mysy.gujarat.gov.in', 'Open', '2026-10-18', 'manual', 'mukhyamantri-yuva-swavalamban-yojana-mysy', NULL),
  (32, 'pudhumai-penn-scheme', 'Pudhumai Penn Scheme', 22, 'National', 4, 'INR', 12000, 12000, '₹1,000/month until the course is completed', 'Annual', NULL, '2026-10-31', 'Applications June–October', 1, 0, 0, NULL, 0, NULL, NULL, 'Female', 'Studied Class 6–12 in a government school (or govt-aided Tamil-medium school); first higher-education course', NULL, 'Monthly support for girls from government schools who go on to college, diploma or ITI in Tamil Nadu.', 'Applied through the college''s nodal officer on the penkalvi portal.', 'https://penkalvi.tn.gov.in', 'Open', '2026-10-18', 'manual', 'pudhumai-penn-scheme', NULL),
  (33, 'vidyasiri-food-and-accommodation-scholarship', 'Vidyasiri Food and Accommodation Scholarship', 23, 'National', 5, 'INR', 15000, 15000, '₹1,500/month for 10 months + ₹1,200 book grant', 'Annual', NULL, NULL, '2026-27 cycle expected; previous cycle closed 31 Aug', 1, 0, 0, NULL, 0, 250000, 55, 'All', 'Not staying in a government hostel; Category-1 limits shown (stricter for 2A/3A/3B)', NULL, 'Karnataka support for food and accommodation costs of backward-class students who could not get a government hostel seat.', 'Apply on Karnataka''s State Scholarship Portal (SSP).', 'https://ssp.postmatric.karnataka.gov.in', 'Open', '2026-10-18', 'manual', 'vidyasiri-food-and-accommodation-scholarship', NULL),
  (34, 'fulbright-nehru-masters-fellowships', 'Fulbright-Nehru Master''s Fellowships', 24, 'International', 9, 'USD', NULL, NULL, 'Fully funded: tuition, monthly living stipend, round-trip airfare, J-1 visa support, accident & sickness cover', 'Annual', NULL, NULL, 'Usually closes mid-May (next: ~May 2027 for 2028-29)', 0, 1, 0, NULL, 0, NULL, 55, 'All', '3+ years of relevant full-time work experience; Indian citizen resident in India; no prior US degree', NULL, 'Fully funded master''s study in the US for Indian professionals with leadership potential in fields such as public policy, public health, economics and urban planning.', 'Apply online to USIEF; shortlisted candidates are interviewed in India.', 'https://www.usief.org.in', 'Open', '2026-10-18', 'manual', 'fulbright-nehru-masters-fellowships', NULL),
  (35, 'chevening-scholarships', 'Chevening Scholarships', 25, 'International', 9, 'GBP', NULL, NULL, 'Fully funded one-year master''s: tuition, monthly living allowance, return economy flight, visa fee', 'Annual', NULL, NULL, '2027-28 round closed 6 Oct 2026; next opens ~Aug 2027', 1, 1, 0, NULL, 0, NULL, NULL, 'All', '2,800+ hours (~2 years) of work experience; must return home for 2 years after the degree', NULL, 'The UK government''s global scholarship for future leaders to do a one-year master''s at any UK university.', 'Apply online with four essays and three UK course choices; interviews at the British High Commission.', 'https://www.chevening.org', 'Open', '2026-10-18', 'manual', 'chevening-scholarships', NULL),
  (36, 'commonwealth-masters-scholarships', 'Commonwealth Master''s Scholarships', 26, 'International', 9, 'GBP', 20544, 2335000, 'Full tuition + £1,712/month stipend (£2,000 in London) + return airfare + study travel grant', 'Annual', NULL, '2026-10-20', 'CSC portal deadline; India''s nominating agency closes earlier', 1, 1, 0, NULL, 0, NULL, NULL, 'All', 'Upper-second-class (2:1) degree; cannot afford UK study otherwise; nominated by national agency (no MBA)', NULL, 'Fully funded one-year taught master''s at a UK university for talented candidates from eligible Commonwealth countries, including India.', 'Apply through your national nominating agency (Ministry of Education for India), then on the CSC portal.', 'https://cscuk.fcdo.gov.uk/masters', 'Open', '2026-10-18', 'manual', 'commonwealth-masters-scholarships', NULL),
  (37, 'rhodes-scholarship-india', 'Rhodes Scholarship (India)', 27, 'International', 9, 'GBP', NULL, NULL, 'Fully funded postgraduate study at the University of Oxford (fees, stipend, flights, visa)', 'Annual', 5, NULL, 'Opens 1 June, closes ~23 July each year', 1, 1, 0, NULL, 0, NULL, NULL, 'All', 'Exceptional academics, character and leadership; age/eligibility per India constituency rules', NULL, 'The world''s oldest international graduate scholarship; five awards each year for Indian candidates to study at Oxford.', 'Apply online; shortlisted candidates attend regional and final interviews.', 'https://www.rhodeshouse.ox.ac.uk/scholarships/apply/india', 'Open', '2026-10-18', 'manual', 'rhodes-scholarship-india', NULL),
  (38, 'inlaks-shivdasani-foundation-scholarship', 'Inlaks Shivdasani Foundation Scholarship', 28, 'International', 9, 'USD', 120000, 10242000, 'Up to US$120,000 for the course: tuition, living, one-way airfare, health allowance', 'Over full course', NULL, NULL, 'Usually opens Jan, closes ~31 March', 0, 1, 0, NULL, 0, NULL, 65, 'All', 'Admission to a top university in the US, UK or Europe; not for engineering, computer science, medicine or MBA', NULL, 'Merit scholarship for outstanding Indian graduates to study at top universities in the US, UK and Europe (excludes engineering, CS, medicine, MBA).', 'Apply online; shortlisted candidates are interviewed.', 'https://www.inlaksfoundation.org', 'Open', '2026-10-18', 'manual', 'inlaks-shivdasani-foundation-scholarship', NULL),
  (39, 'gates-cambridge-scholarship', 'Gates Cambridge Scholarship', 29, 'International', 9, 'GBP', 23152, 2631000, 'Full cost: tuition + £23,152/yr maintenance + visa, health surcharge, airfares', 'Annual', 70, '2026-12-08', 'International round: 8 Dec 2026 or 6 Jan 2027 depending on course', 1, 1, 0, NULL, 1, NULL, NULL, 'All', 'Non-UK citizens applying for a full-time PhD, MLitt or one-year master''s at Cambridge (not MBA)', NULL, 'Full-cost scholarships for outstanding applicants from outside the UK to pursue a postgraduate degree at the University of Cambridge.', 'Apply via the Cambridge Applicant Portal and tick the Gates Cambridge box.', 'https://www.gatescambridge.org', 'Open', '2026-10-18', 'manual', 'gates-cambridge-scholarship', NULL),
  (40, 'eiffel-excellence-scholarship', 'Eiffel Excellence Scholarship', 30, 'International', 9, 'EUR', 14400, 1397000, '€1,200/month (master''s) or €2,000/month (PhD) + travel, insurance, cultural activities', 'Annual', NULL, NULL, 'Institution deadlines Oct–Nov 2026; Campus France closes Jan 2027', 0, 1, 0, NULL, 0, NULL, NULL, 'All', 'Age 29 or under (master''s) / 35 or under (PhD); nominated by a French institution', NULL, 'French government scholarship to attract top international students to master''s and PhD programmes in France.', 'Apply to the French institution, which nominates you to Campus France.', 'https://www.campusfrance.org/en/eiffel-scholarship-program-of-excellence', 'Open', '2026-10-18', 'manual', 'eiffel-excellence-scholarship', NULL);
INSERT INTO scholarships (scholarship_id, slug, name, provider_id, scope, category_id, currency_code, amount_original, amount_inr, amount_note, amount_period, num_awards, deadline, deadline_note, all_fields, all_india, host_any, host_note, open_to_all_nationalities, max_income_inr, min_percentage, gender_eligibility, special_eligibility, required_profile_flag, description, application_process, official_url, status, last_verified, data_source, external_id, fetched_at) VALUES
  (41, 'swiss-government-excellence-scholarships', 'Swiss Government Excellence Scholarships', 31, 'International', 7, 'CHF', 29400, 3031000, 'CHF 2,450/month (PhD up to 36 months; research fellowship 6–12 months)', 'Annual', NULL, '2026-11-10', 'India deadline, 2027-28', 1, 1, 0, NULL, 0, NULL, NULL, 'All', 'Master''s completed by Jul 2027; born after 31 Dec 1991; support letter from a Swiss supervisor', NULL, 'Swiss government PhD scholarships and research fellowships at Swiss universities for graduates from abroad, including India.', 'Apply on the GO ESKAS portal via the Swiss embassy channel for India.', 'https://www.sbfi.admin.ch/en/swiss-government-excellence-scholarships-at-a-glance', 'Open', '2026-10-18', 'manual', 'swiss-government-excellence-scholarships', NULL),
  (42, 'mext-monbukagakusho-japanese-government-scholarship', 'MEXT (Monbukagakusho) Japanese Government Scholarship', 32, 'International', 9, 'JPY', 1728000, 1026000, '≈¥143,000–145,000/month (research students), ≈¥117,000 (undergraduate) + full tuition + airfare', 'Annual', NULL, NULL, 'Embassy route usually opens ~April; exams May–June', 1, 1, 0, NULL, 0, NULL, NULL, 'All', 'Embassy recommendation route: written test and interview', NULL, 'Japanese government scholarship covering tuition, a monthly stipend and airfare for research, undergraduate and other programmes in Japan.', 'Apply through the Embassy of Japan in India (written exam and interview) or via a Japanese university.', 'https://www.in.emb-japan.go.jp/education/japanese_government_scholarships.html', 'Open', '2026-10-18', 'manual', 'mext-monbukagakusho-japanese-government-scholarship', NULL),
  (43, 'global-korea-scholarship-gks', 'Global Korea Scholarship (GKS)', 33, 'International', 9, 'KRW', 10800000, 640000, '≈KRW 900,000/month + tuition (up to KRW 5 million), airfare, settlement, language and completion grants, insurance', 'Annual', 78, NULL, 'Embassy track ~Feb–Mar; university track ~Sep–Oct', 1, 1, 0, NULL, 0, NULL, 80, 'All', '80% CGPA or top 20% of class; age under 25 (UG) / under 40 (graduate); 78 seats reserved for India', NULL, 'Korean government scholarship for undergraduate and graduate degrees in Korea, including a year of Korean language training.', 'Apply via the embassy track or directly to a Korean university (university track).', 'https://www.studyinkorea.go.kr', 'Open', '2026-10-18', 'manual', 'global-korea-scholarship-gks', NULL),
  (44, 'j-n-tata-endowment-loan-scholarship', 'J.N. Tata Endowment Loan Scholarship', 34, 'International', 9, 'INR', 1000000, 1000000, 'Loan scholarship of ₹1–10 lakh (some sources say up to ₹20 lakh) at 2% simple interest; travel grant possible', 'One-time', NULL, NULL, 'Opens January, closes around end-January / March each year', 1, 1, 1, 'Any country', 0, NULL, 60, 'All', 'Indian graduates with an admission offer abroad; partly loan (repayable)', NULL, 'Century-old Tata endowment providing low-interest loan scholarships to Indian graduates for postgraduate study abroad.', 'Apply online, followed by a test and interview.', 'https://www.jntataendowment.org', 'Open', '2026-10-18', 'manual', 'j-n-tata-endowment-loan-scholarship', NULL),
  (45, 'holland-scholarship', 'Holland Scholarship', 35, 'International', 9, 'EUR', 5000, 485000, '€5,000 one-time in the first year', 'One-time', NULL, NULL, 'Usually 1 Feb or 1 May, set by each university', 1, 1, 0, NULL, 0, NULL, NULL, 'All', 'Non-EEA students starting a bachelor''s or master''s at a participating Dutch institution; country list set by each university', NULL, 'One-time grant for talented non-EEA students starting a full-time degree at a participating Dutch university or university of applied sciences.', 'Apply through the Dutch institution''s own scholarship procedure after applying for admission.', 'https://www.studyinnl.org', 'Open', '2026-10-18', 'manual', 'holland-scholarship', NULL),
  (46, 'government-of-ireland-international-education-scholarship-goi-ies', 'Government of Ireland International Education Scholarship (GOI-IES)', 36, 'International', 9, 'EUR', 10000, 970000, '€10,000 stipend + full tuition waiver for one year', 'One-time', NULL, NULL, 'Call usually opens ~Feb, closes ~Mar', 1, 1, 0, NULL, 0, NULL, NULL, 'All', 'Non-EU/EEA students accepted at an Irish higher education institution (final-year UG, master''s, PhD); confirm current eligible-country list', NULL, 'Irish government scholarship offering a stipend and fee waiver for one year of study in Ireland.', 'Apply online to the HEA; institutions confirm admission.', 'https://hea.ie/policy/internationalisation/goi-ies/', 'Open', '2026-10-18', 'manual', 'government-of-ireland-international-education-scholarship-goi-ies', NULL),
  (47, 'k-c-mahindra-scholarships-for-post-graduate-studies-abroad', 'K.C. Mahindra Scholarships for Post-Graduate Studies Abroad', 37, 'International', 9, 'INR', 1000000, 1000000, 'Interest-free loan scholarship: up to ₹10 lakh (top 3 Fellows) / up to ₹5 lakh (others)', 'One-time', NULL, '2026-10-31', 'Per current cycle; verify on site', 1, 1, 1, 'Any country', 0, NULL, NULL, 'All', 'First-class degree; admission (or application) to a reputed foreign university; repayable interest-free', NULL, 'Interest-free loan scholarships from the Mahindra group''s education trust for Indian graduates pursuing postgraduate study abroad.', 'Apply online; shortlisted candidates are interviewed.', 'https://www.kcmet.org', 'Open', '2026-10-18', 'manual', 'k-c-mahindra-scholarships-for-post-graduate-studies-abroad', NULL),
  (48, 'aga-khan-foundation-international-scholarship-programme', 'Aga Khan Foundation International Scholarship Programme', 38, 'International', 9, 'USD', NULL, NULL, 'Tuition and living expenses: 50% grant + 50% loan (5% annual service charge)', 'Annual', NULL, NULL, 'Usually 31 March', 1, 1, 1, 'Any country', 0, NULL, NULL, 'All', 'Outstanding students with no other means of financing; preference for under-30s; resident in India', NULL, 'Need-based scholarship-loan for postgraduate study abroad for outstanding students from select developing countries, including India.', 'Apply to the Aga Khan Foundation office in India.', 'https://the.akdn/en/what-we-do/developing-human-capacity/education/international-scholarships', 'Open', '2026-10-18', 'manual', 'aga-khan-foundation-international-scholarship-programme', NULL),
  (49, 'erasmus-mundus-joint-masters-scholarships', 'Erasmus Mundus Joint Master''s Scholarships', 39, 'International', 9, 'EUR', 16800, 1629000, '€1,400/month + full tuition + up to €3,000/yr travel & installation + insurance', 'Annual', NULL, NULL, 'Programme deadlines mostly Dec 2026 – Feb 2027', 1, 1, 1, 'Any EU country', 1, NULL, NULL, 'All', 'Study in at least two European countries; apply to each joint programme separately', NULL, 'EU-funded scholarships for joint master''s programmes run by consortia of universities across two or more European countries.', 'Choose programmes from the Erasmus Mundus catalogue and apply on each programme''s own portal.', 'https://www.eacea.ec.europa.eu/scholarships/erasmus-mundus-catalogue_en', 'Open', '2026-10-18', 'manual', 'erasmus-mundus-joint-masters-scholarships', NULL),
  (50, 'mitacs-globalink-research-internship-aicte', 'Mitacs Globalink Research Internship (AICTE)', 40, 'International', 3, 'CAD', NULL, NULL, 'Fully funded 12-week research internship: airfare, housing, food stipend, insurance', 'One-time', 300, NULL, '2027 round closed 16 Sep 2026; next opens ~Aug 2027', 0, 1, 0, NULL, 0, NULL, 70, 'All', 'Full-time BE/BTech student with 1–3 semesters remaining; age 18+', NULL, 'Summer research internship at Canadian universities for senior Indian engineering undergraduates, under the Mitacs–AICTE partnership.', 'Apply to 3–10 projects across at least three Canadian provinces.', 'https://www.mitacs.ca', 'Open', '2026-10-18', 'manual', 'mitacs-globalink-research-internship-aicte', NULL),
  (51, 'great-scholarships-india', 'GREAT Scholarships – India', 41, 'International', 9, 'GBP', 10000, 1136000, 'At least £10,000 towards tuition for a one-year master''s', 'One-time', 12, NULL, 'Set by each university', 1, 1, 0, NULL, 0, NULL, NULL, 'All', 'Indian citizens; offer from a participating UK university (list changes each year)', NULL, 'Tuition scholarships from participating UK universities for Indian students on one-year postgraduate courses.', 'Apply for admission to a participating university, then apply for its GREAT scholarship.', 'https://study-uk.britishcouncil.org/scholarships-funding/great-scholarships/india', 'Open', '2026-10-18', 'manual', 'great-scholarships-india', NULL),
  (52, 'knight-hennessy-scholars', 'Knight-Hennessy Scholars', 42, 'International', 9, 'USD', NULL, NULL, 'Full funding for up to 3 years of Stanford graduate study: tuition, living & academic stipend, annual travel', 'Annual', NULL, NULL, '2027 cohort closed 6 Oct 2026; usually opens June', 1, 1, 0, NULL, 1, NULL, NULL, 'All', 'Apply to a full-time Stanford graduate programme; open to all nationalities', NULL, 'Stanford''s flagship graduate scholarship providing full funding and leadership development to scholars from around the world.', 'Submit the Knight-Hennessy application and a separate Stanford graduate programme application.', 'https://knight-hennessy.stanford.edu', 'Open', '2026-10-18', 'manual', 'knight-hennessy-scholars', NULL),
  (53, 'charpak-masters-scholarship', 'Charpak Master''s Scholarship', 43, 'International', 9, 'EUR', 10320, 1001000, '€860/month + visa and Campus France fee waiver + health insurance + housing priority', 'Annual', NULL, NULL, 'Usually early in the year; interviews in April', 1, 1, 0, NULL, 0, NULL, NULL, 'All', 'Indian citizen or OCI; age 30 or under; admitted to a full-time master''s in France', NULL, 'French government scholarship for Indian students pursuing a full-time master''s degree in France.', 'Apply on the Institut Français India scholarship portal; shortlisted candidates have an online interview.', 'https://inde.campusfrance.org', 'Open', '2026-10-18', 'manual', 'charpak-masters-scholarship', NULL),
  (54, 'daad-wise-working-internships-in-science-and-engineering', 'DAAD WISE (Working Internships in Science and Engineering)', 44, 'International', 3, 'EUR', 2802, 272000, '€934/month for 2–3 months + travel subsidy (~€1,075) + health insurance', 'One-time', NULL, '2026-11-05', 'DAAD portal deadline', 0, 1, 0, NULL, 0, NULL, 85, 'All', '85% aggregate / 8.5 CGPA; invitation from a German professor at a public university or research institute', NULL, 'Summer research internship in Germany for top Indian undergraduate science and engineering students.', 'Secure a host professor, then apply on the DAAD portal.', 'https://www2.daad.de/deutschland/stipendium/datenbank/en/', 'Open', '2026-10-18', 'manual', 'daad-wise-working-internships-in-science-and-engineering', NULL),
  (55, 'fulbright-nehru-doctoral-research-fellowships', 'Fulbright-Nehru Doctoral Research Fellowships', 24, 'International', 7, 'USD', NULL, NULL, '6–9 months in the US: monthly stipend, round-trip airfare, J-1 visa support, health cover, affiliation fees', 'Annual', NULL, NULL, 'Usually closes ~July (2027-28 round closed)', 0, 1, 0, NULL, 0, NULL, NULL, 'All', 'Registered for a PhD at an Indian institution; not a government employee; priority fields change yearly', NULL, 'Lets Indian PhD scholars spend 6–9 months doing research at a US institution.', 'Apply online via USIEF/IIE portal; shortlisted candidates interviewed.', 'https://www.usief.org.in/fulbright-fellowships/fellowships-for-indian-citizen/fulbright-nehru-doctoral-research-fellowships', 'Open', '2026-10-18', 'manual', 'fulbright-nehru-doctoral-research-fellowships', NULL),
